package com.muthumol.player.dummy;
import android.graphics.Color;import android.view.*;import android.widget.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=25)
public class CinemaUiTest {
 @Test public void resumeProgressAndRemainingTimeAreBounded(){assertEquals(250,CinemaInfo.progress(900000,3600000));assertEquals(1000,CinemaInfo.progress(5000,1000));assertEquals(0,CinemaInfo.progress(-1000,10000));assertEquals(0,CinemaInfo.progress(1000,0));assertTrue(CinemaInfo.resume(900000,3600000).contains("45 min left"));assertTrue(CinemaInfo.resume(1000,0).contains("Saved position"));}
 @Test public void offlineStatusRequiresCompletionAndErrorsTakePriority(){assertEquals("Offline ready",CinemaInfo.state(true,false,true,100,true,false));assertEquals("Retry playback",CinemaInfo.state(true,true,true,100,true,false));assertTrue(CinemaInfo.state(true,false,false,100,false,false).startsWith("Partially cached"));assertTrue(CinemaInfo.state(true,false,false,100,false,true).startsWith("Downloading"));assertTrue(CinemaInfo.error("Refresh failed; saved movie kept"));assertFalse(CinemaInfo.error("Movie preparation started"));assertTrue(MovieData.isMovieKey("duration:movie"));}
 @Test public void offlineReadinessRejectsMissingAndTruncatedBlocks()throws Exception{
  java.io.File dir=java.nio.file.Files.createTempDirectory("offline-ui").toFile();int n=ReadAheadStore.START_BLOCK;DownloadAndCacheTest.PatternLoader loader=new DownloadAndCacheTest.PatternLoader();
  for(int offset:new int[]{0,2*n})loader.load(offset,n,new java.io.File(dir,offset+".block"),()->false);
  ReadAheadStore.Loader offline=new ReadAheadStore.Loader(){public void load(long at,int size,java.io.File target,java.util.function.BooleanSupplier stop)throws java.io.IOException{throw new java.io.IOException("Offline test");}public void cancel(){}};ReadAheadStore cache=new ReadAheadStore(dir,3L*n,0,()->0,offline,true);try{assertFalse(cache.fullyCached());}finally{cache.closePreservingCompletedBlocks();}
  loader.load(n,n,new java.io.File(dir,n+".block"),()->false);cache=new ReadAheadStore(dir,3L*n,0,()->0,offline,true);
  try{assertTrue(cache.fullyCached());try(java.io.RandomAccessFile f=new java.io.RandomAccessFile(new java.io.File(dir,n+".block"),"rw")){f.setLength(n-1);}assertFalse(cache.fullyCached());}finally{cache.close();}
 }
 @Test public void movieArtworkMetadataSurvivesSerialization(){Movie m=new Movie();m.artwork="YWJj";m.artworkPath="/cached/thumbnail";m.identity="poster-test";Movie restored=Movie.from(m.json());assertEquals(m.artwork,restored.artwork);assertEquals(m.artworkPath,restored.artworkPath);assertEquals(m.cacheIdentity(),restored.cacheIdentity());}
 @Test public void cinemaHomeUpdatesExistingViewsAndShowsContinueAndRetry(){
  org.robolectric.android.controller.ActivityController<MainActivity> c=Robolectric.buildActivity(MainActivity.class).create();MainActivity a=c.get();Movie previous=a.session.movie;ReadAheadStore store=a.session.store;String note=a.session.note;long channel=a.session.channelId;
  try{Movie m=new Movie();m.title="Cinema test movie.mkv";m.uri="file:///cinema-test";m.identity="cinema-test";m.duration=3600;a.session.movie=m;a.session.channelId=42;a.session.store=null;a.session.note="Movie preparation started";a.getSharedPreferences("player",0).edit().putLong("pos:"+m.cacheIdentity(),900000).commit();a.home();assertNotNull(a.poster);assertEquals(250,a.resumeProgress.getProgress());assertTrue(a.heroContinueButton.getText().toString().contains("CONTINUE"));assertTrue(a.resumeSummary.getText().toString().contains("45 min left"));View original=a.heroContinueButton;a.changed();assertSame(original,a.heroContinueButton);a.session.note="Refresh failed";a.changed();assertEquals(View.VISIBLE,a.stateAction.getVisibility());assertEquals("Retry",a.stateAction.getText());assertTrue(a.heroContinueButton.isEnabled());}
  finally{a.session.movie=previous;a.session.store=store;a.session.note=note;a.session.channelId=channel;c.destroy();}
 }
 @Test public void playerMenuUsesSidePanelAndFocusesSelectedTrack(){org.robolectric.android.controller.ActivityController<PlayerActivity> c=null;try{Movie m=new Movie();m.uri="file:///menu-test";android.content.Intent i=new android.content.Intent(RuntimeEnvironment.getApplication(),PlayerActivity.class).putExtra("movies",new org.json.JSONArray().put(m.json()).toString());c=Robolectric.buildActivity(PlayerActivity.class,i).create().start().resume().visible();PlayerActivity a=c.get();Ui.menu(a,"Audio tracks",new String[]{"Track 1","Track 2 ✓"},n->{});android.app.Dialog d=org.robolectric.shadows.ShadowDialog.getLatestDialog();assertTrue((d.getWindow().getAttributes().gravity&Gravity.RIGHT)==Gravity.RIGHT);View focused=d.getCurrentFocus();assertTrue(focused instanceof Button);assertTrue(((Button)focused).getText().toString().contains("Track 2"));d.dismiss();a.release();}finally{if(c!=null)c.destroy();}}
}
